def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - add empty field only if we haven't started yet (empty line case)
            if i == 0:
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] != ',':
                                return None
                            i += 1
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain double quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line):
                # Skip the comma
                i += 1

    return fields

